/* Mocha Mousse Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="mocha-mousse-light"] {
  --background: rgb(239, 239, 231);
  --foreground: rgb(89, 69, 62);
  --card: rgb(239, 239, 231);
  --card-foreground: rgb(89, 69, 62);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(89, 69, 62);
  --primary: rgb(162, 120, 102);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(187, 172, 146);
  --secondary-foreground: rgb(255, 255, 255);
  --muted: rgb(229, 199, 183);
  --muted-foreground: rgb(137, 101, 90);
  --accent: rgb(229, 199, 183);
  --accent-foreground: rgb(89, 69, 62);
  --destructive: rgb(30, 25, 22);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(187, 172, 146);
  --input: rgb(187, 172, 146);
  --ring: rgb(162, 120, 102);
  --chart-1: rgb(162, 120, 102);
  --chart-2: rgb(137, 101, 90);
  --chart-3: rgb(194, 160, 139);
  --chart-4: rgb(187, 172, 146);
  --chart-5: rgb(161, 134, 118);
  --radius: 0.5rem;
  --sidebar: rgb(236, 214, 202);
  --sidebar-foreground: rgb(89, 69, 62);
  --sidebar-primary: rgb(162, 120, 102);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(194, 160, 139);
  --sidebar-accent-foreground: rgb(255, 255, 255);
  --sidebar-border: rgb(161, 134, 118);
  --sidebar-ring: rgb(162, 120, 102);
  --font-sans: DM Sans, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Menlo, monospace;
  --shadow-color: rgba(153, 123, 108, 0.4);
  --shadow-opacity: 0.11;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 2px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 2px 2px 0px 0px hsl(20 18% 51% / 0.06);
  --shadow-xs: 2px 2px 0px 0px hsl(20 18% 51% / 0.06);
  --shadow-sm:
    2px 2px 0px 0px hsl(20 18% 51% / 0.11),
    2px 1px 2px -1px hsl(20 18% 51% / 0.11);
  --shadow:
    2px 2px 0px 0px hsl(20 18% 51% / 0.11),
    2px 1px 2px -1px hsl(20 18% 51% / 0.11);
  --shadow-md:
    2px 2px 0px 0px hsl(20 18% 51% / 0.11),
    2px 2px 4px -1px hsl(20 18% 51% / 0.11);
  --shadow-lg:
    2px 2px 0px 0px hsl(20 18% 51% / 0.11),
    2px 4px 6px -1px hsl(20 18% 51% / 0.11);
  --shadow-xl:
    2px 2px 0px 0px hsl(20 18% 51% / 0.11),
    2px 8px 10px -1px hsl(20 18% 51% / 0.11);
  --shadow-2xl: 2px 2px 0px 0px hsl(20 18% 51% / 0.28);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="mocha-mousse-dark"] {
  --background: rgb(43, 37, 34);
  --foreground: rgb(239, 239, 231);
  --card: rgb(62, 51, 44);
  --card-foreground: rgb(239, 239, 231);
  --popover: rgb(62, 51, 44);
  --popover-foreground: rgb(239, 239, 231);
  --primary: rgb(194, 160, 139);
  --primary-foreground: rgb(43, 37, 34);
  --secondary: rgb(137, 101, 90);
  --secondary-foreground: rgb(239, 239, 231);
  --muted: rgb(89, 69, 62);
  --muted-foreground: rgb(199, 170, 155);
  --accent: rgb(187, 172, 146);
  --accent-foreground: rgb(43, 37, 34);
  --destructive: rgb(229, 116, 116);
  --destructive-foreground: rgb(43, 37, 34);
  --border: rgb(89, 69, 62);
  --input: rgb(89, 69, 62);
  --ring: rgb(194, 160, 139);
  --chart-1: rgb(194, 160, 139);
  --chart-2: rgb(187, 172, 146);
  --chart-3: rgb(162, 120, 102);
  --chart-4: rgb(137, 101, 90);
  --chart-5: rgb(161, 134, 118);
  --radius: 0.5rem;
  --sidebar: rgb(30, 25, 22);
  --sidebar-foreground: rgb(239, 239, 231);
  --sidebar-primary: rgb(194, 160, 139);
  --sidebar-primary-foreground: rgb(30, 25, 22);
  --sidebar-accent: rgb(187, 172, 146);
  --sidebar-accent-foreground: rgb(30, 25, 22);
  --sidebar-border: rgb(89, 69, 62);
  --sidebar-ring: rgb(194, 160, 139);
  --font-sans: DM Sans, sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: Menlo, monospace;
  --shadow-color: rgba(90, 72, 63, 0.5);
  --shadow-opacity: 0.11;
  --shadow-blur: 0px;
  --shadow-spread: 0px;
  --shadow-offset-x: 2px;
  --shadow-offset-y: 2px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 2px 2px 0px 0px hsl(20 18% 30% / 0.06);
  --shadow-xs: 2px 2px 0px 0px hsl(20 18% 30% / 0.06);
  --shadow-sm:
    2px 2px 0px 0px hsl(20 18% 30% / 0.11),
    2px 1px 2px -1px hsl(20 18% 30% / 0.11);
  --shadow:
    2px 2px 0px 0px hsl(20 18% 30% / 0.11),
    2px 1px 2px -1px hsl(20 18% 30% / 0.11);
  --shadow-md:
    2px 2px 0px 0px hsl(20 18% 30% / 0.11),
    2px 2px 4px -1px hsl(20 18% 30% / 0.11);
  --shadow-lg:
    2px 2px 0px 0px hsl(20 18% 30% / 0.11),
    2px 4px 6px -1px hsl(20 18% 30% / 0.11);
  --shadow-xl:
    2px 2px 0px 0px hsl(20 18% 30% / 0.11),
    2px 8px 10px -1px hsl(20 18% 30% / 0.11);
  --shadow-2xl: 2px 2px 0px 0px hsl(20 18% 30% / 0.28);
}
